$finance->pay($first,['valor_pago'=>'253.34','forma_pagamento'=>'pix'],keyP());$paidBefore=$db->get('lancamentos',$first);$finance->pay($second,['valor_pago'=>'10.00','forma_pagamento'=>'pix'],keyP());testP(EducacionalERP\Domain\Money::cents($db->get('lancamentos',$second)['desconto_condicional_aplicado'])===0,'pagamento parcial não concede desconto antecipado');$partialBefore=$db->get('lancamentos',$second);$d=$db->get('contrato_descontos',(int)$d2['iddesconto']);$discounts->remove((int)$d2['iddesconto'],['versao'=>$d['versao']],keyP());testP($db->get('lancamentos',$third)['desconto_incondicional']==='50.00','exclusão remove só um desconto de parcela futura');testP($db->get('lancamentos',$first)===$paidBefore&&$db->get('lancamentos',$second)===$partialBefore,'exclusão preserva baixa integral e parcial');
